class TestConcurrencyProperties:
    """Property-based tests for concurrent scan behavior."""

    @given(
        num_findings=st.integers(min_value=0, max_value=100),
    )
    @settings(max_examples=20, suppress_health_check=[HealthCheck.too_slow])
    @pytest.mark.asyncio
    async def test_concurrent_scan_integrity(self, num_findings, mock_finding_factory):
        """Verify concurrent scans maintain data integrity."""
        findings = [
            mock_finding_factory(
                plugin_id=f"plugin-{i}",
                severity="MEDIUM",
                title=f"Finding {i}",
            )
            for i in range(num_findings)
        ]

        mock_engine = MagicMock()
        mock_engine.scan = AsyncMock(return_value=findings)

        with patch("main.engine", mock_engine):
            # Run multiple concurrent scans
            import asyncio
            tasks = [main.scan_and_serialize() for _ in range(5)]
            results = await asyncio.gather(*tasks)

        # Verify all results are valid JSON and contain correct number of findings
        for result in results:
            parsed = json.loads(result)
            assert len(parsed) == num_findings
            # Verify ordering is preserved
            for i, finding in enumerate(parsed):
                assert finding["plugin_id"] == f"plugin-{i}"


